head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용

scwin.fn_GetPar, scwin.fn_SetPar;
scwin.Isur_cd = "", scwin.Isur_nm = "", scwin.Secugrp_id = "", scwin.Mkt_id = "", scwin.fr_bz_procs_no = "";
scwin.fr_MktId = $c.lc.fn_getMktId();
scwin.vScrenID = "ULDSTF07052.xml";
scwin.vScrenProcTpCd = "";
scwin.TR_JOB;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    gDepCd = js_dep_cd;

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)			
    //상장심사팀만 표시 
    var vHeadString = "VALUE:STRING(50),TEXT:STRING(50),DEP_CD:STRING(4)";
    //dts_DEP_CD.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_DEP_CD.insertRow();
    dts_DEP_CD.setCellData(1, "VALUE", "");
    dts_DEP_CD.setCellData(1, "TEXT", "전체");
    dts_DEP_CD.setCellData(1, "DEP_CD", "");

    // 유가인 경우 2520, 2540 만 표시
    if ("1" == scwin.fr_MktId) {
        dts_DEP_CD.insertRow();
        dts_DEP_CD.setCellData(2, "VALUE", "2520");
        dts_DEP_CD.setCellData(2, "TEXT", "상장심사1팀");
        dts_DEP_CD.setCellData(2, "DEP_CD", "2520");
        dts_DEP_CD.insertRow();
        dts_DEP_CD.setCellData(3, "VALUE", "2540");
        dts_DEP_CD.setCellData(3, "TEXT", "상장심사2팀");
        dts_DEP_CD.setCellData(3, "DEP_CD", "2540");
    } else if ("2" == scwin.fr_MktId) {
        //코스닥인 경우  3320,  3330, 3350 만 표시
        dts_DEP_CD.insertRow();
        dts_DEP_CD.setCellData(2, "VALUE", "3320");
        dts_DEP_CD.setCellData(2, "TEXT", "상장심사1팀");
        dts_DEP_CD.setCellData(2, "DEP_CD", "3320");
        dts_DEP_CD.insertRow();
        dts_DEP_CD.setCellData(3, "VALUE", "3330");
        dts_DEP_CD.setCellData(3, "TEXT", "상장심사2팀");
        dts_DEP_CD.setCellData(3, "DEP_CD", "3330");

        /*dts_DEP_CD.AddRow();
dts_DEP_CD.setNameString(4, "VALUE","3350") ;
dts_DEP_CD.setNameString(4, "TEXT","상장심사3팀") ;
dts_DEP_CD.setNameString(4, "DEP_CD","3350") ;*/

        dts_DEP_CD.insertRow();
        dts_DEP_CD.setCellData(4, "VALUE", "3E10");
        dts_DEP_CD.setCellData(4, "TEXT", "상장심사1팀(기술)");
        dts_DEP_CD.setCellData(4, "DEP_CD", "3E10");
        dts_DEP_CD.insertRow();
        dts_DEP_CD.setCellData(5, "VALUE", "3E20");
        dts_DEP_CD.setCellData(5, "TEXT", "상장심사2팀(기술)");
        dts_DEP_CD.setCellData(6, "DEP_CD", "3E20");
        dts_DEP_CD.insertRow();
        dts_DEP_CD.setCellData(6, "VALUE", "3E30");
        dts_DEP_CD.setCellData(6, "TEXT", "상장심사3팀(기술)");
        dts_DEP_CD.setCellData(6, "DEP_CD", "3E30");
    }
    //cmb_DEP_CD.redraw = true;	
    //dts_DEP_CD.Reset();

    if ("1" == scwin.fr_MktId) {
        //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
        dts_EMP_NO.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + gDepCd;
        dts_EMP_NO.Reset();
    } else if ("2" == scwin.fr_MktId) {
        dts_EMP_NO.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + gDepCd;
        dts_EMP_NO.Reset();
        if (gDepCd.substring(0, 2) == "33") {
            dts_temp.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + "3E00";
            dts_temp.Reset();
        } else if (gDepCd.substring(0, 2) == "3E") {
            dts_temp.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + "3300";
            dts_temp.Reset();
        }
        for (var i = 2; i <= dts_temp.getTotalRow(); i++) {
            /*   alert(dts_temp.NameString(i, "VALUE"));
               alert(dts_temp.NameString(i, "TEXT"));
               alert(dts_temp.NameString(i, "DEP_CD"));*/
            dts_EMP_NO.insertRow();
            if (dts_temp.getCellData(i, "VALUE") != "") {
                dts_EMP_NO.setCellData(dts_EMP_NO.getTotalRow(), "VALUE", dts_temp.getCellData(i, "VALUE"));
                dts_EMP_NO.setCellData(dts_EMP_NO.getTotalRow(), "TEXT", dts_temp.getCellData(i, "TEXT"));
                dts_EMP_NO.setCellData(dts_EMP_NO.getTotalRow(), "DEP_CD", dts_temp.getCellData(i, "DEP_CD"));
            }
        }
        setTimeout("fn_SetCombo()", 500);
    }
    //setTimeout("fn_SetCombo()", 500);

    //alert(dts_examprn.NameString(1,"LIST_DELIB_SCHDL_DD"));

};
scwin.fn_SetCombo = function() {
    var depCd = dts_examprn.getCellData(1, "DEP_CD");
    //alert(depCd);
    $c.stf.setObjectValue(cmb_DEP_CD, depCd);
    var empNo = dts_examprn.getCellData(1, "EMP_NO");
    //alert(empNo);	
    $c.stf.setObjectValue(cmb_EMP_NO, empNo);
};
scwin.fn_read_sync = function() {
    // 조회
    var url = "/lstinvstg/InvstgAssgn.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=readInvstgChrgAssgnDtl";
    url += "&BZ_PROCS_NO=" + vBzProcsNo;
    dts_examprn.DataID = encodeURI(url);
    dts_examprn.Reset();
};
scwin.fn_CheckForm = function() {
    if (edt_Bfchg_Std_Ind_Cd.getText() == "") {
        $c.win.alert("[변경전]데이타가 없어서 처리할수 없습니다.");
        edt_Bfchg_Std_Ind_Cd.focus();
        return false;
    }
    return true;
};
scwin.fn_trs = function() {
    var schdlDd = edit_LIST_DELIB_SCHDL_DD.GetSelClipText(0, 8);
    scwin.vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    trs_Save.Action = $c.lc.fn_encodeNSession("/lstinvstg/InvstgAssgn.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + scwin.vScrenProcTpCd + "&method=modifyInvstgChrgAssgn");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_examprn)";
    trs_Save.Parameters = "TRS_IDX=U" + ", EXAMPRN_EMP_NO=" + $c.stf.getObjectValue(cmb_EMP_NO) + ", LIST_DELIB_SCHDL_DD=" + schdlDd + ", BZ_PROCS_NO=" + vBzProcsNo;
    trs_Save.Post();
};
scwin.fn_parentRefresh = function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
};
scwin.btn_schdl_dt_onclick = function() {
    popUpCalendar2(edit_LIST_DELIB_SCHDL_DD);
};
scwin.dts_EMP_NO_OnLoadCompleted = function(rowcount) {
    setTimeout("fn_SetCombo()", 300);
};
scwin.dts_examprn_OnLoadError = function() {
    $c.stf.alert_error(dts_examprn);
};
scwin.dts_examprn_OnLoadCompleted = function(rowcount) {
    //alert(dts_examprn.NameString(1,"LIST_DELIB_SCHDL_DD"));
    //setObjectValue( edit_LIST_DELIB_SCHDL_DD, dts_examprn.NameString(1,"LIST_DELIB_SCHDL_DD") ) ;
    edit_LIST_DELIB_SCHDL_DD.PutSelClipText(0, 8, dts_examprn.getCellData(1, "LIST_DELIB_SCHDL_DD"));
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
};
scwin.trs_Save_OnSuccess = async function() {
    $c.lc.fn_alertMsg('S1');
    scwin.fn_parentRefresh();
    await $c.frame.CloseFrame();
};
scwin.btn_Save_onclick = function() {
    var selectEmp = $c.stf.getObjectValue(cmb_EMP_NO);
    if ("" != selectEmp) {
        scwin.fn_trs();
    } else {
        $c.win.alert("담당자를 선택해주십시요");
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.cmb_DEP_CD_OnSelChange2 = function() {
    gDepCd = $c.stf.getObjectValue(cmb_DEP_CD);
    //alert(gDepCd);
    if (gDepCd == '') {
        $c.stf.setObjectValue(cmb_EMP_NO, '');
    }
    dts_EMP_NO.UseFilter = true;
    dts_EMP_NO.Filter();
    dts_EMP_NO.sort("DEP_CD", 0);
    //dts_EMP_NO.sort(); // W-Craft 주석처리 

};
scwin.cmb_DEP_CD_OnSelected = function() {

};
scwin.dts_EMP_NO_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_EMP_NO.getCellData(row, "DEP_CD") == gDepCd || dts_EMP_NO.getCellData(row, "DEP_CD") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.gform_onload = function() {
    var parentWin = $c.frame.path("../");
    vBzProcsNo = parentWin.clickBzProcsNo;
    scwin.fn_read_sync(); // 조회수행
    scwin.fn_SetCode();
};
